WITH with_gaps AS (SELECT *, CASE WHEN LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) IS NULL OR reading_ts > LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) + INTERVAL '45' MINUTE THEN 1 ELSE 0 END AS is_new_burst FROM device_readings), sessionized AS (SELECT *, SUM(is_new_burst) OVER (PARTITION BY device_code ORDER BY reading_ts, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM with_gaps), scored AS (SELECT id, device_code, temp_c, pressure, firmware, is_new_burst, ROW_NUMBER() OVER w_running AS row_seq, LAST_VALUE(humidity, TRUE) OVER w_hist AS last_known_humidity, LAST_VALUE(pressure, TRUE) OVER (PARTITION BY device_code ORDER BY session_no, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_pressure FROM sessionized WINDOW w_running AS (PARTITION BY device_code ORDER BY session_no, id), w_hist AS (ORDER BY pressure, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)), enriched AS (SELECT *, NTILE(10) OVER (PARTITION BY device_code ORDER BY is_new_burst, id) AS is_new_burst_bucket, DENSE_RANK() OVER (PARTITION BY device_code ORDER BY last_known_humidity DESC NULLS FIRST) AS last_known_humidity_dense_rank, ROUND(temp_c / SUM(temp_c) OVER (PARTITION BY device_code), 4) AS temp_c_share, NTILE(4) OVER (ORDER BY pressure, id) AS pressure_bucket FROM scored WHERE last_known_pressure BETWEEN 995 AND 1018), metrics AS (SELECT *, NTILE(5) OVER w_grp AS is_new_burst_bucket_2, SUM(last_known_humidity) OVER (PARTITION BY device_code ORDER BY is_new_burst, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_last_known_humidity, AVG(last_known_humidity_dense_rank) OVER w_part AS last_known_humidity_dense_rank_avg_5 FROM enriched WINDOW w_grp AS (PARTITION BY device_code ORDER BY is_new_burst DESC, id), w_part AS (PARTITION BY device_code ORDER BY temp_c_share, id ROWS BETWEEN 5 PRECEDING AND CURRENT ROW)), enriched_device_readings AS (SELECT id, firmware, is_new_burst, last_known_humidity, is_new_burst_bucket, last_known_humidity_dense_rank, cumulative_last_known_humidity, last_known_humidity_dense_rank_avg_5, LEAD(is_new_burst_bucket_2) OVER w_ordered AS next_is_new_burst_bucket_2, LAG(temp_c_share) OVER w_ordered AS prev_temp_c_share, LEAD(temp_c_share) OVER w_ordered AS next_temp_c_share, ROW_NUMBER() OVER w_ordered AS event_seq, LEAD(temp_c_share, 1) OVER w_running AS next_temp_c_share_2 FROM metrics WINDOW w_ordered AS (PARTITION BY device_code ORDER BY last_known_pressure, id), w_running AS (PARTITION BY device_code ORDER BY last_known_humidity, id)), with_windows AS (SELECT *, LAST_VALUE(next_temp_c_share) IGNORE NULLS OVER (ORDER BY prev_temp_c_share, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_next_temp_c_share, ROW_NUMBER() OVER (ORDER BY next_temp_c_share_2, id) AS event_seq_2, FIRST_VALUE(is_new_burst_bucket, TRUE) OVER (ORDER BY next_temp_c_share_2, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_is_new_burst_bucket, NTILE(4) OVER (ORDER BY last_known_humidity, id) AS last_known_humidity_bucket, AVG(next_temp_c_share_2) OVER (ORDER BY last_known_humidity_dense_rank, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS next_temp_c_share_2_avg_3 FROM enriched_device_readings), kept_keys AS (SELECT id FROM with_windows EXCEPT SELECT id FROM device_readings WHERE reading_ts < '2024-09-18'), reconciled AS (SELECT s.* FROM with_windows s INNER JOIN kept_keys k ON s.id = k.id) SELECT id, is_new_burst_bucket, last_known_humidity_dense_rank, cumulative_last_known_humidity, last_known_humidity_dense_rank_avg_5, next_temp_c_share, event_seq, next_temp_c_share_2, last_known_next_temp_c_share FROM reconciled ORDER BY last_known_humidity_dense_rank_avg_5 DESC;
